import type { TowerSnapshot } from '../bus/snapshots.js';

export function towerSnapshotWouldChange(prev: TowerSnapshot, next: TowerSnapshot): boolean {
  return (
    prev.language !== next.language ||
    prev.titleLabel !== next.titleLabel ||
    prev.recordLabel !== next.recordLabel ||
    prev.ticketsLabel !== next.ticketsLabel ||
    prev.marksLabel !== next.marksLabel ||
    prev.startLabelHtml !== next.startLabelHtml ||
    prev.towerRecord !== next.towerRecord ||
    prev.combatTickets !== next.combatTickets ||
    prev.triumphMarks !== next.triumphMarks ||
    prev.startDisabled !== next.startDisabled ||
    prev.batchVisible !== next.batchVisible ||
    prev.batchHtml !== next.batchHtml ||
    prev.batchSig !== next.batchSig ||
    prev.maxBatchRuns !== next.maxBatchRuns ||
    prev.towerBatchSize !== next.towerBatchSize ||
    prev.relicAutoVisible !== next.relicAutoVisible ||
    prev.relicAutoHtml !== next.relicAutoHtml ||
    prev.relicAutoSig !== next.relicAutoSig ||
    prev.ascentMemoryVisible !== next.ascentMemoryVisible ||
    prev.ascentMemoryHtml !== next.ascentMemoryHtml ||
    prev.ascentMemorySig !== next.ascentMemorySig ||
    prev.subwayTabVisible !== next.subwayTabVisible ||
    prev.subwayTitleLabel !== next.subwayTitleLabel ||
    prev.subwayRecordLabel !== next.subwayRecordLabel ||
    prev.subwayBestStreak !== next.subwayBestStreak ||
    prev.subwaySetProgressSig !== next.subwaySetProgressSig ||
    prev.subwayTodaySetProgressLabel !== next.subwayTodaySetProgressLabel ||
    prev.subwayTodayBestStreak !== next.subwayTodayBestStreak ||
    prev.subwayTodayWagonsCleared !== next.subwayTodayWagonsCleared ||
    prev.subwayTodayCurrentWagon !== next.subwayTodayCurrentWagon ||
    prev.subwayBpLabel !== next.subwayBpLabel ||
    prev.subwayBP !== next.subwayBP ||
    prev.subwayStartLabelHtml !== next.subwayStartLabelHtml ||
    prev.subwayStartDisabled !== next.subwayStartDisabled ||
    prev.subwayActive !== next.subwayActive ||
    prev.subwayRunProgress !== next.subwayRunProgress ||
    prev.subwayRunProgressLabel !== next.subwayRunProgressLabel ||
    prev.subwayDescription !== next.subwayDescription ||
    prev.subwayWagonProgressHint !== next.subwayWagonProgressHint ||
    prev.subwayWagonLabel !== next.subwayWagonLabel ||
    prev.subwayCurrentWagon !== next.subwayCurrentWagon
  );
}
