/**
 * @file src/lib/towerSnapshot.ts
 * Read-only snapshot for TowerPanel.
 */

import type { GameRuntime } from '../types/game.js';
import type { TowerSnapshot } from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import { towerSnapshotWouldChange } from '../stores/towerSnapshotDiff.js';
import {
  buildTowerAscentMemoryPanelHtml,
  buildTowerBatchPanelHtml,
  buildTowerRelicAutoPanelHtml,
} from '@snapshot/tower';
import {
  clampTowerBatchSize,
  getTowerBatchTicketsRequired,
  getTowerMaxBatchRuns,
  isTowerClimbQuestActive,
} from './towerBatchRuns.ts';
import { getSubwaySetProgressRows, getSubwayCurrentWagonIndex } from './subwayDailySet.ts';
import { getCombatEntryTicketCost } from './combatEntryTickets.ts';
import { isSubwayIntroQuestActive, canAffordSubwayRunTickets } from '../../subwaySystem.ts';
import { canStartChampionsTowerRun, getChampionsTowerProgressLabel } from '../../championsTowerSystem.ts';
const CROWN_PASS_IMG =
  'https://raw.githubusercontent.com/msikma/pokesprite/master/items/key-item/crown-pass.png';

function towerT(
  game: GameRuntime,
  key: string,
  fallback: string,
  vars?: Record<string, string | number>,
): string {
  let out: string;
  if (typeof game.t === 'function') {
    const translated = vars ? game.t(key, vars) : game.t(key);
    out = translated && translated !== key ? translated : fallback;
  } else {
    out = fallback;
  }
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
  }
  return out;
}

/** Deferred placeholder templates — game.t strips unknown {vars} unless preserved. */
function towerTemplate(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t !== 'function') return fallback;

  const placeholderKeys = [...fallback.matchAll(/\{(\w+)\}/g)].map((m) => m[1]);
  const preserveVars: Record<string, string> = {};
  for (const k of placeholderKeys) {
    preserveVars[k] = `{${k}}`;
  }

  const got = game.t(key, preserveVars);
  return got && got !== key ? got : fallback;
}

function buildTowerStartLabelHtml(game: GameRuntime): string {
  const batchSize = clampTowerBatchSize(game);
  const ticketsRequired = getTowerBatchTicketsRequired(game, batchSize);
  const ticketWord = ticketsRequired === 1
    ? towerT(game, 'tower.startTicketSingular', 'ticket')
    : towerT(game, 'tower.startTicketPlural', 'tickets');
  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  if (batchSize > 1) {
    const perRunHint = towerT(game, 'tower.batch.perRunTicketHint', 'requis (1/run)');
    return `${towerT(game, 'tower.startLabel', "Lancer l'ascension")} - ${ticketsRequired} ${ticketImg} ${ticketWord} ${perRunHint} (${batchSize} ${towerT(game, 'tower.batch.runsShort', 'runs')})`;
  }
  if (ticketsRequired === 0) {
    return `${towerT(game, 'tower.startLabel', "Lancer l'ascension")} - ${towerT(game, 'tower.startFreeQuest', 'gratuit (quete)')}`;
  }
  return `${towerT(game, 'tower.startLabel', "Lancer l'ascension")} - ${ticketsRequired} ${ticketImg} ${towerT(game, 'tower.startRequirement', 'requis')}`;
}

function isTowerStartDisabled(game: GameRuntime): boolean {
    const batchSize = clampTowerBatchSize(game);
    const ticketsRequired = getTowerBatchTicketsRequired(game, batchSize);
    if (game.championsTowerState?.isActive) return true;
    if (isTowerClimbQuestActive(game) && batchSize === 1) return false;
    return (game.combatTickets ?? 0) < ticketsRequired;
}

function buildSubwayStartLabelHtml(game: GameRuntime): string {
  const ticketsRequired = isSubwayIntroQuestActive(game) ? 0 : getCombatEntryTicketCost();
  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  if (ticketsRequired === 0) {
    return `${towerT(game, 'subway.startLabel', 'Lancer un wagon')} - ${towerT(game, 'subway.startFreeQuest', 'gratuit (quête)')}`;
  }
  return `${towerT(game, 'subway.startLabel', 'Lancer un wagon')} - ${ticketsRequired} ${ticketImg}`;
}

function isSubwayStartDisabled(game: GameRuntime): boolean {
  if (game.subwayState?.isActive || game.towerState?.isActive || game.championsTowerState?.isActive) return true;
  return !canAffordSubwayRunTickets(game);
}

function buildChampionsStartLabelHtml(game: GameRuntime): string {
  const ticketsRequired = getCombatEntryTicketCost();
  const ticketImg = `<img src="${CROWN_PASS_IMG}" class="combat-ticket-inline" alt="" loading="lazy" decoding="async" fetchpriority="low">`;
  return `${towerT(game, 'champions.startLabel', 'Lancer la Tour des Champions')} - ${ticketsRequired} ${ticketImg}`;
}

function isChampionsStartDisabled(game: GameRuntime): boolean {
  return canStartChampionsTowerRun(game) != null;
}

export function buildTowerSnapshot(game: GameRuntime): TowerSnapshot {
  const relic = buildTowerRelicAutoPanelHtml(game);
  const ascent = buildTowerAscentMemoryPanelHtml(game);
  const batch = buildTowerBatchPanelHtml(game);
  const progressRows = getSubwaySetProgressRows(game);
  const todayRow = progressRows.find((r) => r.isToday) ?? progressRows[0];
  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  return {
    language,
    titleLabel: towerT(game, 'tower.title', 'Tour de Combat'),
    recordLabel: towerT(game, 'tower.recordLabel', 'Record Personnel : Étage'),
    ticketsLabel: towerT(game, 'tower.ticketsLabel', 'Tickets de Combat :'),
    marksLabel: towerT(game, 'tower.marksLabel', 'Marques du Triomphe :'),
    startLabelHtml: buildTowerStartLabelHtml(game),
    towerRecord: String(game.towerRecord ?? 0),
    combatTickets: String(game.combatTickets ?? 0),
    triumphMarks: String(game.triumphMarks ?? 0),
    startDisabled: isTowerStartDisabled(game),
    batchVisible: batch.visible,
    batchHtml: batch.html,
    batchSig: batch.sig,
    maxBatchRuns: String(getTowerMaxBatchRuns(game)),
    towerBatchSize: String(clampTowerBatchSize(game)),
    relicAutoVisible: relic.visible,
    relicAutoHtml: relic.html,
    relicAutoSig: relic.sig,
    ascentMemoryVisible: ascent.visible,
    ascentMemoryHtml: ascent.html,
    ascentMemorySig: ascent.sig,
    subwayTabVisible: !!(game.unlockedFeatures && game.unlockedFeatures.subwayTab),
    subwayTitleLabel: towerT(game, 'subway.title', 'Battle Subway'),
    subwayRecordLabel: towerT(game, 'subway.recordLabel', 'Meilleure série :'),
    subwayBestStreak: String(game.subwayBestStreak ?? 0),
    subwayBpLabel: towerT(game, 'subway.bpLabel', 'Points Subway :'),
    subwayBP: String(game.subwayBP ?? 0),
    subwaySetProgressTitle: towerT(game, 'subway.setProgressTitle', 'Progression par set'),
    subwayTodaySetProgressLabel: towerT(
      game,
      'subway.todaySetProgress',
      'Set du jour — {label}',
      { label: todayRow?.label ?? '' },
    ),
    subwayTodayBestStreak: String(todayRow?.bestStreak ?? 0),
    subwayTodayWagonsCleared: String(todayRow?.wagonsCleared ?? 0),
    subwayTodayCurrentWagon: String(
      todayRow ? getSubwayCurrentWagonIndex(game, todayRow.setId) : getSubwayCurrentWagonIndex(game),
    ),
    subwaySetProgressWeeklyTemplate: towerTemplate(game, 'subway.setProgressWeekly', 'Progression hebdo : {n}'),
    subwaySetProgressPersonalBestTemplate: towerTemplate(game, 'subway.setProgressPersonalBest', 'Meilleur wagon : {n}'),
    subwaySetProgressCurrentWagonTemplate: towerTemplate(
      game,
      'subway.setProgressCurrentWagon',
      'Wagon : {n}',
    ),
    subwaySetProgressRows: progressRows.map((row) => ({
      setId: row.setId,
      dayIndex: row.dayIndex,
      label: row.label,
      themeType: row.themeType,
      bestStreak: String(row.bestStreak),
      wagonsCleared: String(row.wagonsCleared),
      currentWagon: String(getSubwayCurrentWagonIndex(game, row.setId)),
      isToday: row.isToday,
    })),
    subwaySetProgressSig: progressRows
      .map((r) => `${r.setId}:${r.bestStreak}:${r.wagonsCleared}:${getSubwayCurrentWagonIndex(game, r.setId)}:${r.isToday ? 1 : 0}`)
      .join('|'),
    subwayStartLabelHtml: buildSubwayStartLabelHtml(game),
    subwayStartDisabled: isSubwayStartDisabled(game),
    subwayActive: !!(game.subwayState && game.subwayState.isActive),
    subwayRunProgress: game.subwayState?.isActive
      ? `${game.subwayState.winsThisRun}/7`
      : '',
    subwayRunProgressLabel: towerT(game, 'subway.runProgressLabel', 'Série en cours'),
    subwayDescription: towerT(
      game,
      'subway.description',
      '7 combats dresseur par wagon. Stats brutes — pas de résonance régionale. Chaque wagon coûte 1 Ticket de Combat (partagé avec la Tour). Les Points Subway servent à la boutique.',
    ),
    subwayWagonProgressHint: towerT(
      game,
      'subway.wagonProgressHint',
      'Chaque wagon est plus difficile (+2 niveaux, +6 % stats). La progression des wagons repart à zéro chaque semaine. Un wagon complet (7/7) rapporte 1 Point Subway.',
    ),
    subwayWagonLabel: towerT(game, 'subway.wagonLabel', 'Wagon actuel'),
    subwayCurrentWagon: String(getSubwayCurrentWagonIndex(game)),
    championsTabVisible: !!(game.unlockedFeatures && game.unlockedFeatures.championsTowerTab),
    championsTitleLabel: towerT(game, 'champions.title', 'Tour des Champions'),
    championsBestCycleLabel: towerT(game, 'champions.bestCycle', 'Meilleur cycle :'),
    championsBestCycle: String(game.championsTowerBestCycle ?? 0),
    championsTotalCycles: String(game.championsTowerTotalCycles ?? 0),
    championsStartLabelHtml: buildChampionsStartLabelHtml(game),
    championsStartDisabled: isChampionsStartDisabled(game),
    championsActive: !!(game.championsTowerState && game.championsTowerState.isActive),
    championsProgressLabel: getChampionsTowerProgressLabel(game),
    championsDescription: towerT(
      game,
      'champions.description',
      'Enchaînez les 9 ligues Pokémon. Pas de soin entre dresseurs d\'une même ligue ; soin complet entre chaque ligue. Après Paldea, cycle 2 avec difficulté accrue.',
    ),
  };
}

let lastTowerSnapshot: TowerSnapshot | null = null;

/** @internal Vitest only */
export function resetTowerSnapshotDedupForTests(): void {
  lastTowerSnapshot = null;
}

export function notifyTowerChanged(game: GameRuntime): void {
  const tower = buildTowerSnapshot(game);
  if (lastTowerSnapshot && !towerSnapshotWouldChange(lastTowerSnapshot, tower)) return;
  lastTowerSnapshot = tower;
  publish({ type: Evt.TOWER_CHANGED, tower });
}
