type GameCtor = { prototype: Record<string, unknown> };
type ThisGame = GameRuntime;

function ctText(
    game: GameRuntime,
    fr: string,
    en: string,
    vars: Record<string, string | number> = {},
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    let out = lang === 'en' ? en : fr;
    for (const [k, v] of Object.entries(vars)) {
        out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
    return out;
}

function notifyChampionsTowerUi(game: GameRuntime): void {
    notifyTowerChanged(game);
}

export function isChampionsTowerUnlocked(game: GameRuntime): boolean {
    return !!(game.unlockedFeatures?.championsTowerTab);
}

export function canStartChampionsTowerRun(game: GameRuntime): string | null {
    if (!isChampionsTowerUnlocked(game)) {
        return ctText(game, 'Tour des Champions non débloquée.', 'Champions Tower not unlocked.');
    }
    if (game.championsTowerState?.isActive) {
        return ctText(game, 'Une run est déjà en cours.', 'A run is already in progress.');
    }
    if (game.towerState?.isActive) {
        return ctText(game, 'Terminez la Tour de Combat d\'abord.', 'Finish the Battle Tower first.');
    }
    if (game.subwayState?.isActive) {
        return ctText(game, 'Terminez le Battle Subway d\'abord.', 'Finish the Battle Subway first.');
    }
    if (game.arenaState?.active) {
        return ctText(game, 'Terminez le combat d\'arène d\'abord.', 'Finish the arena battle first.');
    }
    const ticketsRequired = getCombatEntryTicketCost();
    if (ticketsRequired > 0 && !canAffordCombatEntryTicket(game, ticketsRequired)) {
        return ctText(game, 'Ticket de combat requis.', 'Combat ticket required.');
    }
    return null;
}

function beginChampionsTowerSegment(game: GameRuntime): void {
    const state = game.championsTowerState;
    if (!state?.isActive) return;

    const built = buildChampionsTowerTrainerTeam(
        game,
        state.leagueId,
        state.trainerIndex,
        state.cycle,
    );
    state.enemyTeam = built.team;
    state.trainerName = built.trainerName;
    state.trainerSpriteKey = built.trainerSpriteKey;
    state.currentEnemyIndex = 0;

    game.currentEnemy = arrayAt(state.enemyTeam, 0) ?? null;
    if (game.currentEnemy) {
        game.currentEnemy._focusSashUsed = false;
        applyHazardEntryTalentOnEnemyEntry(game, game.currentEnemy as ICreature);
    }
    game.combatState = 'starting';
    game.combatStartTime = Date.now();
    resetCombatTurnTally(game);
    game.triggerAutoSelect?.();

    const eliteDef = typeof game.getEliteFourDefinition === 'function'
        ? game.getEliteFourDefinition(state.leagueId) as { name?: string } | null
        : null;
    logMessage(ctText(
        game,
        'Cycle {cycle} — {league} — {trainer} envoie {pokemon} !',
        'Cycle {cycle} — {league} — {trainer} sends {pokemon}!',
        {
            cycle: state.cycle,
            league: eliteDef?.name ?? state.leagueId,
            trainer: state.trainerName,
            pokemon: game.currentEnemy?.name ?? '???',
        },
    ));
}

export function initChampionsTowerRunState(game: GameRuntime): void {
    healTeamForTowerRun(game);
    Creature.setResonanceGameRef(game);
    game.playerTeam.forEach((c) => c.recalculateStats?.());

    game.championsTowerState = {
        isActive: true,
        cycle: 1,
        leagueIndex: 0,
        trainerIndex: 0,
        currentEnemyIndex: 0,
        enemyTeam: [],
        leagueId: CHAMPIONS_TOWER_LEAGUE_IDS[0],
        trainerName: '',
        trainerSpriteKey: 'youngster',
        runStats: {
            cyclesCompleted: 0,
            leaguesCleared: 0,
            combatsWon: 0,
            startCycle: 1,
            marksGained: 0,
        },
    };

    if (game.activeCreatureIndex != null && game.playerTeam[game.activeCreatureIndex]) {
        game.currentPlayerCreature = game.playerTeam[game.activeCreatureIndex] ?? null;
    }
    if (game.currentPlayerCreature) {
        game.currentPlayerCreature._focusSashUsed = false;
    }

    beginChampionsTowerSegment(game);
    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'combat', 'team']);
    notifyChampionsTowerUi(game);
}

export function startChampionsTowerRunLogic(game: GameRuntime): void {
    const block = canStartChampionsTowerRun(game);
    if (block) {
        logMessage(block);
        return;
    }

    if (game.arenaState?.active) {
        if (typeof game.resetArenaState === 'function') game.resetArenaState();
        else if (game.arenaState) game.arenaState.active = false;
    }
    if (game.gymTrainerState?.active) game.gymTrainerState = null;

    const ticketsRequired = getCombatEntryTicketCost();
    if (ticketsRequired > 0 && !tryConsumeCombatEntryTicket(game, ticketsRequired)) {
        return;
    }

    if (typeof game.enterGameContext === 'function') {
        game.enterGameContext('tower');
    }

    logMessage(ctText(
        game,
        'Tour des Champions — enchaînez les 9 ligues ! Résonance active, pas de soin intra-ligue.',
        'Champions Tower — clear all 9 leagues! Resonance active, no heal within a league.',
    ));

    initChampionsTowerRunState(game);
}

function awardChampionsTowerLeagueMarks(game: GameRuntime): void {
    const marks = BALANCE.CHAMPIONS_TOWER.TRIUMPH_MARKS_PER_LEAGUE ?? 3;
    game.triumphMarks = (Number(game.triumphMarks) || 0) + marks;
    if (game.stats) {
        game.stats.totalTriumphMarksEarned = (game.stats.totalTriumphMarksEarned || 0) + marks;
    }
    if (game.championsTowerState?.runStats) {
        game.championsTowerState.runStats.marksGained = (game.championsTowerState.runStats.marksGained || 0) + marks;
    }
}

function advanceToNextLeague(game: GameRuntime): void {
    const state = game.championsTowerState;
    if (!state) return;

    awardChampionsTowerLeagueMarks(game);
    if (state.runStats) state.runStats.leaguesCleared += 1;

    if (isLastLeagueInCycle(state)) {
        const cycleBonus = BALANCE.CHAMPIONS_TOWER.TRIUMPH_MARKS_PER_CYCLE ?? 25;
        game.triumphMarks = (Number(game.triumphMarks) || 0) + cycleBonus;
        if (game.stats) {
            game.stats.totalTriumphMarksEarned = (game.stats.totalTriumphMarksEarned || 0) + cycleBonus;
            game.stats.championsTowerCycles = (game.stats.championsTowerCycles || 0) + 1;
        }
        game.championsTowerTotalCycles = (game.championsTowerTotalCycles || 0) + 1;
        game.championsTowerBestCycle = Math.max(game.championsTowerBestCycle || 0, state.cycle);
        if (state.runStats) {
            state.runStats.cyclesCompleted += 1;
            state.runStats.marksGained = (state.runStats.marksGained || 0) + cycleBonus;
        }
        if (typeof game.checkAchievements === 'function') {
            game.checkAchievements('championsTowerCycles');
        }
        if (typeof game.checkSpecialQuests === 'function') {
            game.checkSpecialQuests('champions_tower_cycle_completed', { cycle: state.cycle });
        }
        state.cycle += 1;
        state.leagueIndex = 0;
        state.trainerIndex = 0;
        state.leagueId = getChampionsTowerLeagueId(0);
        logMessage(ctText(
            game,
            'Cycle {cycle} terminé ! Retour à la Ligue Kanto (difficulté augmentée).',
            'Cycle {cycle} complete! Back to Kanto League (increased difficulty).',
            { cycle: state.cycle - 1 },
        ));
    } else {
        state.leagueIndex += 1;
        state.trainerIndex = 0;
        state.leagueId = getChampionsTowerLeagueId(state.leagueIndex);
    }

    if (shouldHealBetweenLeagues()) {
        healTeamForTowerRun(game);
    }

    beginChampionsTowerSegment(game);
}

export function advanceChampionsTowerAfterPokemonWinLogic(game: GameRuntime): void {
    const state = game.championsTowerState;
    if (!state?.isActive) return;

    const expMult = BALANCE.CHAMPIONS_TOWER.VICTORY_EXP_LEVEL_MULT ?? 0.08;
    const enemy = game.currentEnemy;
    const expGain = enemy
        ? Math.floor(enemy.level * expMult * (game.getExpMultiplier?.() ?? 1))
        : 0;
    if (expGain > 0) {
        game.playerTeam.forEach((c) => c.gainExp?.(expGain));
    }
    if (state.runStats) state.runStats.combatsWon += 1;

    state.currentEnemyIndex += 1;
    if (state.currentEnemyIndex < state.enemyTeam.length) {
        game.currentEnemy = arrayAt(state.enemyTeam, state.currentEnemyIndex) ?? null;
        if (game.currentEnemy) {
            game.currentEnemy._focusSashUsed = false;
            game.currentEnemy.clearStatusEffect?.();
            applyHazardEntryTalentOnEnemyEntry(game, game.currentEnemy as ICreature);
        }
        logMessage(ctText(
            game,
            '{trainer} envoie {pokemon} !',
            '{trainer} sends {pokemon}!',
            { trainer: state.trainerName, pokemon: game.currentEnemy?.name ?? '???' },
        ));
        game.combatState = 'fighting';
        if (game.currentPlayerCreature) game.currentPlayerCreature.actionGauge = 0;
        if (game.currentEnemy) game.currentEnemy.actionGauge = 0;
        return;
    }

    if (!isLastTrainerInLeague(game, state)) {
        state.trainerIndex += 1;
        beginChampionsTowerSegment(game);
        game.combatState = 'fighting';
        return;
    }

    advanceToNextLeague(game);
    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'combat', 'team']);
    notifyChampionsTowerUi(game);
}

export function endChampionsTowerRunLogic(game: GameRuntime, isForfeit: boolean): void {
    const state = game.championsTowerState;
    if (!state?.isActive) return;

    if (isForfeit) {
        logMessage(ctText(game, 'Tour des Champions abandonnée.', 'Champions Tower forfeited.'));
    } else {
        logMessage(ctText(
            game,
            'Défaite — Cycle {cycle}, ligue {league}.',
            'Defeat — Cycle {cycle}, league {league}.',
            { cycle: state.cycle, league: state.leagueIndex + 1 },
        ));
    }

    if (typeof game.leaveGameContext === 'function') {
        game.leaveGameContext();
    }

    game.championsTowerState = emptyChampionsTowerState();
    game.combatState = 'waiting';
    game.lastCombatTime = Date.now();
    game.currentEnemy = null;

    game.playerTeam.forEach((c) => {
        (c as CreatureData & { heal?: () => void }).heal?.();
    });

    updateZoneInfo(game);
    publishZoneChanged();
    game.updateDisplay(['tower', 'combat', 'team']);
    notifyChampionsTowerUi(game);
    game.saveGame?.();
}

export function applyChampionsTowerSystem(GameClass: GameCtor): void {
    GameClass.prototype.startChampionsTowerRun = function (this: ThisGame): void {
        startChampionsTowerRunLogic(this);
    };

    GameClass.prototype.forfeitChampionsTowerRun = function (this: ThisGame): void {
        endChampionsTowerRunLogic(this, true);
    };

    GameClass.prototype.isChampionsTowerUnlocked = function (this: ThisGame): boolean {
        return isChampionsTowerUnlocked(this);
    };

    GameClass.prototype.getChampionsTowerProgressLabel = function (this: ThisGame): string {
        return getChampionsTowerProgressLabel(this);
    };
}

export function ensureChampionsTowerOnLoad(game: GameRuntime): void {
    if (!game.championsTowerState) {
        game.championsTowerState = emptyChampionsTowerState();
    } else {
        game.championsTowerState = normalizeChampionsTowerState(game.championsTowerState);
    }
    game.championsTowerBestCycle = Math.max(0, Math.floor(Number(game.championsTowerBestCycle) || 0));
    game.championsTowerTotalCycles = Math.max(0, Math.floor(Number(game.championsTowerTotalCycles) || 0));
}

export function getChampionsTowerProgressLabel(game: GameRuntime): string {
    const state = game.championsTowerState;
    if (!state?.isActive) return '';
    const eliteDef = typeof game.getEliteFourDefinition === 'function'
        ? game.getEliteFourDefinition(state.leagueId) as { name?: string } | null
        : null;
    return ctText(
        game,
        'Cycle {cycle} — {league} — {trainer}',
        'Cycle {cycle} — {league} — {trainer}',
        {
            cycle: state.cycle,
            league: eliteDef?.name ?? `Ligue ${state.leagueIndex + 1}/${CHAMPIONS_TOWER_LEAGUE_COUNT}`,
            trainer: state.trainerName,
        },
    );
}
